// Room "P1 dining room" (interior designer's part): a 3 x 3 dining room, x 26..28, z 14..16, feet at y 2.
// The focal piece is the table at the room's centre, under a hanging lantern. One chair on the north side (its seat
// faces the table); the south side stays open so the west and east doorways connect across the room. A barrel sideboard
// with a flower pot sits in the north-east corner, out of every doorway's first cell. Light is one hanging lantern
// over the table.
import { porchLantern } from "../vocab.mjs";
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // table (fence post with a top slab) at (27,15), and the north chair at (27,14); the south chair is left out so
  // the room stays a lane (diningSet places both chairs, so the table is set by hand)
  g.set(27, 2, 15, ...B.fence("oak"));
  g.set(27, 3, 15, "oak_slab", { type: "top", waterlogged: "false" });
  g.set(27, 2, 14, ...B.stairs("oak", "north", "bottom"));

  // sideboard: a barrel with its lid up in the north-east corner, a potted flower on top
  g.set(28, 2, 14, "barrel", { facing: "up", open: "false" });
  g.set(28, 3, 14, "potted_poppy");

  // the focal light: a lantern hanging over the table from the ceiling block above it
  porchLantern(g, { x: 27, y: 4, z: 15 });
}
